import type { SVGProps } from "react";
import Icon from "@mdi/react";
import { mdiRedo } from "@mdi/js";

/**
 * The combined icon set. Two Figma sources, one React set, per request:
 *
 * - "Icon library — plain stroke icons": small utility glyphs (close, send,
 *   menu, etc). No formal three-paragraph Figma description exists for this
 *   section — only that subtitle. Documented here as-is, not invented.
 * - "Colored icon family — accent-tinted icons": larger illustrative icons
 *   with a bold + on-bold (or subtle + on-subtle) color pair each, drawn
 *   from accent/pro tokens.
 *
 * Each icon is one scalable SVG (viewBox preserved, no fixed width/height) —
 * Figma models "size" as separate fixed-pixel component variants per icon
 * (24/12/16), but that's the same artwork rendered at different sizes, not
 * different content. Sizing is IconSlot's job (drop any of these into an
 * IconSlot via its `icon` prop) — duplicating per-icon size variants here
 * would just re-implement what IconSlot already does.
 *
 * KNOWN GAP: send-01, menu-01, and notification-01 use a raw #1a1a1a fill
 * in Figma that isn't bound to any variable and matches no token in
 * tokens.json. Left as a literal hex per instruction, flagged here rather
 * than silently invented or substituted. plus-01 had the same issue but
 * was changed to text/primary per direct instruction (it needed to read as
 * white/light against dark surfaces, e.g. inside buttonIcon's Secondary
 * variant, which has no currentColor override of its own).
 */

