/**
 * KNOWN DEVIATION: every other icon in this file is a hand-built SVG
 * matching Figma exactly (see this file's own header comment) — no redo
 * glyph exists in this project's own icon set or in Figma's library, and
 * per direct instruction this one is sourced from the `@mdi/react` +
 * `@mdi/js` Material Design Icons package instead of being hand-drawn.
 * `size="100%"` (not a fixed px value like `size={1}`) so it still scales
 * inside `IconSlot`'s own sizing system — a fixed size would render with
 * an inline style that CSS can't override, breaking at every `IconSlot`
 * step other than the one it happened to be tuned for.
 */
export function Redo01() {
  return <Icon path={mdiRedo} size="100%" />;
}

